#!/usr/bin/env python3
import subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent
commands=[('final-opc-clippy', ['cargo', 'clippy', '--locked', '--release', '-p', 'litchi-opc', '--all-targets', '--all-features', '--', '-D', 'warnings']), ('final-opc-tests', ['cargo', 'test', '--locked', '--release', '-p', 'litchi-opc', '--all-features', '--', '--test-threads=1', '--nocapture']), ('final-pptx-cross-copy-tests', ['cargo', 'test', '--locked', '--release', '-p', 'litchi-pptx', '--test', 'source_backed_cross_copy', '--test', 'source_backed_cross_copy_adversarial', '--', '--test-threads=1']), ('final-harness-tests', ['cargo', 'test', '--locked', '--release', '--manifest-path', 'tools/perf-baseline/Cargo.toml', '--', '--test-threads=1']), ('final-harness-feature-bins', ['cargo', 'test', '--locked', '--release', '--manifest-path', 'tools/perf-baseline/Cargo.toml', '--all-features', '--bin', 'litchi-perf-baseline-alloc', '--bin', 'xlsb_crud', '--bin', 'xls_source_attribution', '--', '--test-threads=1']), ('final-opc-doc', ['cargo', 'doc', '--locked', '--release', '-p', 'litchi-opc', '--no-deps', '--all-features']), ('final-workspace-check', ['cargo', 'check', '--locked', '--release', '--workspace', '--all-targets', '--no-default-features', '--exclude', 'litchi-iwa*', '--exclude', 'litchi-keynote', '--exclude', 'litchi-numbers*', '--exclude', 'litchi-pages', '--features', 'litchi/odf']), ('final-format', ['rustfmt', '+1.98.1', '--edition', '2024', '--check', '--config', 'skip_children=true', 'crates/litchi-opc/src/source_backed.rs', 'crates/litchi-opc/tests/source_part_transfer.rs', 'crates/litchi-opc/fuzz/fuzz_targets/parse_opc.rs']), ('final-boundaries', ['python3', '-B', 'tools/check_crate_boundaries.py'])]
for tag,argv in commands:
    result=subprocess.run([sys.executable,'-B',str(ROOT/'check.py'),'--tag',tag,'--',*argv])
    if result.returncode:raise SystemExit(result.returncode)
